package app.loki.vecthere

import app.loki.vecthere.dialogs.TRANSLATED_DIALOGS
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals

// Generated by egui2compose.
/**
 * A dialog in the menu has to do something: either its own OK runs a command, or it opens that
 * command's form from the engine's params doc. One that does neither is hidden. Without this, the
 * dialogs whose command the reader could not find sat in the menu with an OK that only closed them.
 */
class DialogsWiredTest {
    private val ids = Json.parseToJsonElement(File("src/jvmTest/resources/engine-commands.json").readText()).jsonArray
        .map { it.jsonObject["id"]!!.jsonPrimitive.content }.toSet()

    @Test
    fun mappedDialogsNameARealCommand() {
        val bad = TRANSLATED_DIALOGS.filter { it.command != null && it.command !in ids }.map { "${it.title}: ${it.command}" }
        assertEquals(emptyList(), bad)
    }

    @Test
    fun noDialogInTheMenuRunsNothing() {
        val registry = File("src/commonMain/kotlin/app/loki/vecthere/dialogs/TranslatedDialogs.kt").readLines()
        val dir = File("src/commonMain/kotlin/app/loki/vecthere/dialogs")
        val dead = dir.listFiles { f -> f.name.endsWith("Dialog.kt") }!!.filter { !it.readText().contains("onRun(\"") }.map { it.name.removeSuffix(".kt") }
            .filter { fn -> registry.any { l -> l.contains("-> $fn(") && !l.contains("command =") && !l.contains("hidden = true") } }
        assertEquals(emptyList(), dead, "in the menu but runs nothing: $dead")
    }
}
